17: package uk.gov.hmrc.softdrinksindustrylevy.models
18: 
19: import play.api.libs.json._
20: import scala.language.implicitConversions
21: 
22: /** Utility class for creating json formatters for enumerations.
23:   */
24: object EnumUtils {
25:   def enumReads[E <: Enumeration](`enum`: E): Reads[`enum`.Value] = new Reads[`enum`.Value] {
26:     def reads(json: JsValue): JsResult[`enum`.Value] = json match {
27:       case JsString(s) =>
28:         `enum`.values.find(_.toString == s) match {
29:           case Some(value) => JsSuccess(value)
30:           case None =>
31:             JsError(
32:               s"Enumeration expected of type: '${`enum`.getClass}'," ++
33:                 s" but it does not appear to contain the value: '$s'"
34:             )
35:         }
36:       case _ => JsError("String value expected")
37:     }
38:   }
39: 
40:   implicit def enumWrites[E <: Enumeration](`enum`: E): Writes[`enum`.Value] = new Writes[`enum`.Value] {
41:     def writes(v: `enum`.Value): JsValue = JsString(v.toString)
42:   }
43: 
44:   implicit def enumFormat[E <: Enumeration](`enum`: E): Format[`enum`.Value] =
45:     Format(enumReads(`enum`), enumWrites(`enum`))
46: 
47: }
